"""Interpretação humana dos experimentos da Etapa 6; não integra o compilador."""


def finding(group, cls, validity, change, analysis, *, tags=(), priority='média', effort=None, recovery='sim'):
    return dict(primary_cause=group, feasibility=cls, validity=validity, recovery=recovery,
        required_change=change, analysis=analysis, tags=list(tags), priority=priority,
        effort=effort or {'A':'baixo','B':'médio','C':'alto','D':'alto','E':'baixo'}[cls])


